#[cfg(feature="native-ocio")]
mod native{
use kimo_core::{color::ocio_config::Config,effects::Frame,commands::{Session,dispatch}};use serde_json::json;
const CONFIG:&str=include_str!("data/minimal_aces.ocio");
#[test]fn synthetic_view_transform_lifetime_alpha(){let p=Config::from_text(CONFIG).unwrap().display_processor("ACEScg","Test monitor","Gamma2 test (not ACES ODT)").unwrap();let mut f=Frame{w:1,h:1,d:vec![0.25,0.25,0.25,0.5]};p.apply(&mut f).unwrap();assert!((f.d[0]-0.5).abs()<1e-6);assert_eq!(f.d[3],0.5);}
#[test]fn invalid_view_and_names(){let c=Config::from_text(CONFIG).unwrap();for(s,d,v)in[("bad","Test monitor","Gamma2 test (not ACES ODT)"),("ACEScg","wrong","Gamma2 test (not ACES ODT)"),("ACEScg","Test monitor","wrong"),("ACEScg","Test monitor","bad\0")]{assert!(c.display_processor(s,d,v).is_err());}}
#[test]fn official_aces2_display(){let Ok(path)=std::env::var("KIMO_TEST_NATIVE_ACES_CONFIG")else{return};let c=Config::from_file(path).unwrap();let p=c.display_processor("ACEScg","sRGB - Display","ACES 2.0 - SDR 100 nits (Rec.709)").unwrap();let mut f=Frame{w:2,h:1,d:vec![0.18,0.18,0.18,0.5,4.,1.,0.2,0.]};p.apply(&mut f).unwrap();assert!(f.d.iter().all(|x|x.is_finite()));assert_eq!(f.d[3],0.5);assert_eq!(f.d[7],0.);assert!(f.d[0]>0.&&f.d[0]<1.);let a=f.d.clone();let mut g=Frame{w:2,h:1,d:vec![0.18,0.18,0.18,0.5,4.,1.,0.2,0.]};p.apply(&mut g).unwrap();assert_eq!(a,g.d);}
#[test]fn render_tool_nonmutating_and_domain_rejection(){let mut s=Session::new();let path=concat!(env!("CARGO_MANIFEST_DIR"),"/tests/data/minimal_aces.ocio");let a=json!({"config_path":path,"source":"ACEScg","display":"Test monitor","view":"Gamma2 test (not ACES ODT)","time":0.,"path":format!("/tmp/ocio-view-{}.png",std::process::id()),"output_encoding":"sRGB_SDR"});assert!(dispatch(&mut s,"render_ocio_display_view",&a).is_err());dispatch(&mut s,"project_set",&json!({"width":16,"height":16})).unwrap();dispatch(&mut s,"set_color_pipeline",&json!({"settings":{"enabled":true,"working_gamut":3}})).unwrap();let tr=dispatch(&mut s,"add_track",&json!({})).unwrap()["track_id"].clone();dispatch(&mut s,"add_clip",&json!({"track_id":tr,"source_type":"solid","color":[0.25,0.25,0.25],"start":0,"duration":1})).unwrap();let before=serde_json::to_value(&s.project).unwrap();let r=dispatch(&mut s,"render_ocio_display_view",&a).unwrap();assert_eq!(r["configured_project_output_applied"],false);assert_eq!(before,serde_json::to_value(&s.project).unwrap());let r=dispatch(&mut s,"transform_ocio_view_samples",&json!({"config_path":path,"source":"ACEScg","display":"Test monitor","view":"Gamma2 test (not ACES ODT)","rgba":[0.25,0.25,0.25,0.5]})).unwrap();assert!((r["rgba"][0].as_f64().unwrap()-0.5).abs()<1e-6);}
}
#[cfg(not(feature="native-ocio"))]
#[test]fn view_tools_fail_closed(){use kimo_core::commands::{Session,dispatch};let mut s=Session::new();for name in ["render_ocio_display_view","transform_ocio_view_samples"]{assert!(dispatch(&mut s,name,&serde_json::json!({})).unwrap_err().contains("native-ocio"));}}
#[cfg(feature="native-ocio")]
#[test]fn configured_look_included_and_invalid_input_transactional(){use kimo_core::{color::ocio_config::Config,effects::Frame};let base=include_str!("data/minimal_aces.ocio");let text=base.replace("colorspace: DisplayGamma2}","colorspace: DisplayGamma2, looks: double}").replace("colorspaces:","looks:\n  - !<Look>\n    name: double\n    process_space: ACEScg\n    transform: !<MatrixTransform> {matrix: [2,0,0,0, 0,2,0,0, 0,0,2,0, 0,0,0,1]}\n\ncolorspaces:");let c=Config::from_text(&text).unwrap();let p=c.display_processor("ACEScg","Test monitor","Gamma2 test (not ACES ODT)").unwrap();let mut f=Frame{w:1,h:1,d:vec![0.25,0.25,0.25,0.3]};p.apply(&mut f).unwrap();assert!((f.d[0]-0.5f32.sqrt()).abs()<1e-6);assert_eq!(f.d[3],0.3);f.d[3]=2.;let before=f.d.clone();assert!(p.apply(&mut f).is_err());assert_eq!(f.d,before);}
